1	import java.awt.event.ActionListener;
2	import java.util.*;
3	
4	/**
5	 * A simple predator-prey simulator, based on a rectangular field
6	 * containing different organisms.
7	 *
8	 * @version 2022.03.02
9	 */
10	public class Simulator
11	{
12	    private static boolean playingSimulation = false;
13	    private static int remainingSteps;
14	
15	    private static final Random rand = Randomizer.getRandom();
16	
17	    // Constants representing configuration information for the simulation.
18	    // The default width for the grid.
19	    private static final int DEFAULT_WIDTH = 240;
20	    // The default depth of the grid.
21	    private static final int DEFAULT_DEPTH = 160;
22	
23	    // A map of the creation probabilities for the organisms in the simulation
24	    private static Map<Class<?>, Double> CREATION_PROBABILITIES = Map.ofEntries(
25	            Map.entry(Coyote.class, 0.010),
26	            Map.entry(Deer.class, 0.080),
27	            Map.entry(Wolf.class, 0.010),
28	            Map.entry(Eagle.class, 0.01),
29	            Map.entry(Mouse.class, 0.080),
30	            Map.entry(Grass.class, 0.030),
31	            Map.entry(Hunter.class, 0.03)
32	
33	    );
34	
35	    // Maximum number of hunters in the simulation
36	    private static final int HUNTER_LIMIT = 5;
37	    private static int HUNTER_COUNT = 0;
38	
39	
40	    // List of actors in the field.
41	    private List<Actor> actors;
42	    // The current state of the field.
43	    private Field field;
44	    // The current step of the simulation.
45	    private int step;
46	    // A graphical view of the simulation.
47	    private SimulatorView view;
48	    // Environment in the simulation.
49	    private Environment environment;
50	
51	
52	    /**
53	     * A simulator constructor to set the CREATION_PROBABILITY of each actor.
54	     * This constructor can be used to test different combinations of probabilities to find an optimal combination
55	     *
56	     * @param GrassProbability Probability of Grass being generated
57	     * @param DeerProbability Probability of Deer being generated
58	     * @param CoyoteProbability Probability of Coyote being generated
59	     * @param WolfProbability Probability of Wolf being generated
60	     * @param EagleProbability Probability of Eagle being generated
61	     * @param HunterProbability Probability of Hunter being generated
62	     * @param MouseProbability Probability of Mouse being generated
63	     */
64	    public Simulator(double GrassProbability, double DeerProbability, double CoyoteProbability, double WolfProbability, double EagleProbability, double HunterProbability, double MouseProbability){
65	        this(DEFAULT_WIDTH, DEFAULT_DEPTH);
66	
67	        CREATION_PROBABILITIES = Map.ofEntries(
68	                Map.entry(Coyote.class, CoyoteProbability),
69	                Map.entry(Deer.class, DeerProbability),
70	                Map.entry(Wolf.class, WolfProbability),
71	                Map.entry(Eagle.class, EagleProbability),
72	                Map.entry(Mouse.class, MouseProbability),
73	                Map.entry(Grass.class, GrassProbability),
74	                Map.entry(Hunter.class, HunterProbability)
75	        );
76	
77	        actors = new ArrayList<>();
78	        field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
79	        environment = new Environment(new Time(), new Weather());
80	
81	        reset();
82	    }
83	
84	    /**
85	     * Construct a simulation field with default size.
86	     */
87	    public Simulator()
88	    {
89	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
90	    }
91	
92	    /**
93	     * Create a simulation field with the given size.
94	     * @param depth Depth of the field. Must be greater than zero.
95	     * @param width Width of the field. Must be greater than zero.
96	     */
97	    public Simulator(int depth, int width)
98	    {
99	        if(width <= 0 || depth <= 0) {
100	            System.out.println("The dimensions must be greater than zero.");
101	            System.out.println("Using default values.");
102	            depth = DEFAULT_DEPTH;
103	            width = DEFAULT_WIDTH;
104	        }
105	
106	        actors = new ArrayList<>();
107	        field = new Field(depth, width);
108	        environment = new Environment(new Time(), new Weather());
109	
110	        // Create a view of the state of each location in the field.
111	        view = new SimulatorView(depth, width);
112	        for(Class cls : SimulationInfo.DEFAULT_COLOR_MAP.keySet()) {
113	            view.setColor(cls, SimulationInfo.DEFAULT_COLOR_MAP.get(cls));
114	        }
115	
116	        // adding additional buttons to the GUI
117	        view.addLongButtonListener(longButtonListener);
118	        view.addOneStepButtonListener(startButtonListener);
119	        view.addStopButtonListener(stopButtonListener);
120	        view.addResetButtonListener(resetButtonListener);
121	
122	        // Setup a valid starting point.
123	        reset();
124	    }
125	
126	    /**
127	     * Run the simulation from its current state for a reasonably long period,
128	     * (4000 steps).
129	     */
130	    public void runLongSimulation()
131	    {
132	        remainingSteps += 4000;
133	        simulate(remainingSteps);
134	    }
135	
136	    /**
137	     * Whenever the startButton is pressed,the simulateOneStep()
138	     * method is called.
139	     */
140	    private ActionListener startButtonListener = e -> {
141	        if(playingSimulation){
142	            System.out.println("Stop the simulation first");
143	        }
144	        else {
145	            playingSimulation = true;
146	            simulateOneStep();
147	            playingSimulation = false;
148	        }
149	    };
150	
151	    /**
152	     * Whenever the stopButton is pressed, the simulation is stopped.
153	     */
154	    private ActionListener stopButtonListener = e -> {
155	        playingSimulation = false;
156	        Thread.currentThread().interrupt();
157	    };
158	
159	    /**
160	     * Whenever the resetButton is pressed, the simulation is reset.
161	     */
162	    private ActionListener resetButtonListener = e -> {
163	        playingSimulation = false;
164	        reset();
165	    };
166	
167	    /**
168	     * Whenever the longButton is pressed,runLongSimulation() is called.
169	     */
170	    private ActionListener longButtonListener = e -> {
171	        Thread runLongSimThread = new Thread("SimulationRunThread"){
172	            public void run() { runLongSimulation(); }
173	        };
174	
175	        if (!playingSimulation){
176	            runLongSimThread.start();
177	        }
178	        else{
179	            System.out.println("Stop the simulation first");
180	        }
181	    };
182	
183	
184	    /**
185	     * Run the simulation from its current state for the given number of steps.
186	     * Stop before the given number of steps if it ceases to be viable.
187	     * @param numSteps The number of steps to run for.
188	     */
189	    public void simulate(int numSteps)
190	    {
191	        playingSimulation = true;
192	        remainingSteps = numSteps;
193	
194	        int backupCounter = 1;
195	        while(playingSimulation){
196	            for(int step = 1; step <= numSteps && view.isViable(field); step++) {
197	                simulateOneStep();
198	                backupCounter++;
199	//            delay(60);   // uncomment this to run more slowly
200	            }
201	            if(!view.isViable(field)){
202	                // System.out.println("STEPS COMPLETED: "+backupCounter);
203	                // uncomment this while optimizing for population stability
204	                Thread.currentThread().interrupt();
205	                if(backupCounter > SimulationInfo.HIGHEST_STEPS){
206	                    // If multiple instances of the simulation are created in the same session (for testing),
207	                    // the fields in SimulationInfo can be used for optimizing the default probabilities
208	                    SimulationInfo.HIGHEST_STEPS = backupCounter;
209	                    SimulationInfo.HIGHEST_STEP_PROBS = this.CREATION_PROBABILITIES;
210	                }
211	                playingSimulation = false;
212	                break;
213	            }
214	        }
215	        remainingSteps = numSteps - backupCounter;
216	    }
217	
218	    /**
219	     * Run the simulation from its current state for a single step.
220	     * Iterate over the whole field updating the state of each
221	     * organism.
222	     */
223	    public void simulateOneStep()
224	    {
225	        if(!playingSimulation){ return; }
226	        step++;
227	        environment.getTime().incrementTime();
228	        environment.getWeather().checkWeatherChange(step);
229	
230	
231	        // Provide space for newborn animals.
232	        List<Actor> newActors = new ArrayList<>();
233	        // Let all actors act.
234	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
235	            Actor actor = it.next();
236	            if(actor instanceof Animal){
237	               if(((Animal) actor).isAwake(environment)) {
238	                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
239	                       ((Animal) actor).setDead();
240	                   }
241	                   actor.act(newActors, environment);
242	               }
243	            }
244	            else {
245	                actor.act(newActors, environment);
246	            }
247	
248	            if(actor instanceof Plant){
249	                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
250	                    ((Plant) actor).incrementGrowth();
251	                }
252	            }
253	
254	            if(! actor.isAlive()) {
255	                it.remove();
256	            }
257	
258	
259	
260	        }
261	        actors.addAll(newActors);
262	        plantGrassInPatches();
263	
264	        view.showStatus(step, environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString(), field);
265	    }
266	
267	    /**
268	     * Randomly generate grass in free patches on the field, only if it is raining
269	     */
270	    private void plantGrassInPatches(){
271	        // new grass is randomly added in patches
272	        for(Location location:field.getRandomFreePatches(CREATION_PROBABILITIES.get(Grass.class))){
273	            if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class) && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
274	                Grass grass = new Grass(field, location);
275	                actors.add(grass);
276	            }
277	        }
278	    }
279	
280	    /**
281	     * Reset the simulation to a starting position.
282	     */
283	    public void reset()
284	    {
285	        step = 0;
286	        actors.clear();
287	        populate();
288	        environment.getTime().reset();
289	
290	        // Show the starting state in the view.
291	        view.showStatus(step,environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString().toString(), field);
292	    }
293	
294	    /**
295	     * Randomly populate the field with organisms.
296	     */
297	    private void populate()
298	    {
299	        Random rand = Randomizer.getRandom();
300	        field.clear();
301	        for(int row = 0; row < field.getDepth(); row++) {
302	            for(int col = 0; col < field.getWidth(); col++) {
303	                Animal.Gender sex = Randomizer.getRandomSex();
304	                Location location = new Location(row, col);
305	
306	                if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class)) {
307	                    Grass grass = new Grass(field, location);
308	                    actors.add(grass);
309	                }
310	
311	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Deer.class)) {
312	                    Deer deer = new Deer(true, field, location, sex);
313	                    actors.add(deer);
314	                }
315	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Coyote.class)) {
316	                    Coyote coyote = new Coyote(true, field, location, sex);
317	                    actors.add(coyote);
318	                }
319	
320	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Wolf.class)) {
321	                    Wolf wolf = new Wolf(true, field, location, sex);
322	                    actors.add(wolf);
323	                }
324	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Eagle.class)) {
325	                    Eagle eagle = new Eagle(true, field, location, sex);
326	                    actors.add(eagle);
327	                }
328	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Mouse.class)) {
329	                    Mouse mouse = new Mouse(true, field, location, sex);
330	                    actors.add(mouse);
331	                }
332	
333	                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Hunter.class)) {
334	                    if(!(HUNTER_COUNT >= HUNTER_LIMIT)){
335	                        Hunter hunter = new Hunter(field, location, environment);
336	                        actors.add(hunter);
337	                        HUNTER_COUNT++;
338	                    }
339	                }
340	                // else leave the location empty.
341	            }
342	        }
343	    }
344	
345	    /**
346	     * Pause for a given time.
347	     * @param millisec  The time to pause for, in milliseconds
348	     */
349	    private void delay(int millisec)
350	    {
351	        try {
352	            Thread.sleep(millisec);
353	        }
354	        catch (InterruptedException ie) {
355	            // wake up
356	        }
357	    }
358	
359	
360	}
