1	import java.util.*;
2	
3	/**
4	 * Represent a rectangular grid of field positions.
5	 * Each position is able to store a single animal.
6	 *
7	 * @version 2022.03.02
8	 */
9	public class Field
10	{
11	    // A random number generator for providing random locations.
12	    private static final Random rand = Randomizer.getRandom();
13	
14	    // The depth and width of the field.
15	    private int depth, width;
16	    // Storage for the animals.
17	    private Object[][] field;
18	
19	    private Set<Location> emptyLocs = new HashSet<>();
20	
21	    /**
22	     * Represent a field of the given dimensions.
23	     * @param depth The depth of the field.
24	     * @param width The width of the field.
25	     */
26	    public Field(int depth, int width)
27	    {
28	        this.depth = depth;
29	        this.width = width;
30	        field = new Object[depth][width];
31	    }
32	    
33	    /**
34	     * Empty the field.
35	     */
36	    public void clear()
37	    {
38	        for(int row = 0; row < depth; row++) {
39	            for(int col = 0; col < width; col++) {
40	                field[row][col] = null;
41	            }
42	        }
43	    }
44	    
45	    /**
46	     * Clear the given location.
47	     * @param location The location to clear.
48	     */
49	    public void clear(Location location)
50	    {
51	        field[location.getRow()][location.getCol()] = null;
52	    }
53	    
54	    /**
55	     * Place an animal at the given location.
56	     * If there is already an animal at the location it will
57	     * be lost.
58	     * @param animal The animal to be placed.
59	     * @param row Row coordinate of the location.
60	     * @param col Column coordinate of the location.
61	     */
62	    public void place(Object animal, int row, int col)
63	    {
64	        place(animal, new Location(row, col));
65	    }
66	    
67	    /**
68	     * Place an animal at the given location.
69	     * If there is already an animal at the location it will
70	     * be lost.
71	     * @param animal The animal to be placed.
72	     * @param location Where to place the animal.
73	     */
74	    public void place(Object animal, Location location)
75	    {
76	        field[location.getRow()][location.getCol()] = animal;
77	    }
78	    
79	    /**
80	     * Return the animal at the given location, if any.
81	     * @param location Where in the field.
82	     * @return The animal at the given location, or null if there is none.
83	     */
84	    public Object getObjectAt(Location location)
85	    {
86	        return getObjectAt(location.getRow(), location.getCol());
87	    }
88	    
89	    /**
90	     * Return the animal at the given location, if any.
91	     * @param row The desired row.
92	     * @param col The desired column.
93	     * @return The animal at the given location, or null if there is none.
94	     */
95	    public Object getObjectAt(int row, int col)
96	    {
97	        return field[row][col];
98	    }
99	
100	    /**
101	     * Returns the field of the simulation. 
102	     */
103	    public Object[][] getField()
104	    {
105	        return field;
106	    }
107	    
108	    /**
109	     * Generate a random location that is adjacent to the
110	     * given location, or is the same location.
111	     * The returned location will be within the valid bounds
112	     * of the field.
113	     * @param location The location from which to generate an adjacency.
114	     * @return A valid location within the grid area.
115	     */
116	    public Location randomAdjacentLocation(Location location)
117	    {
118	        List<Location> adjacent = adjacentLocations(location);
119	        return adjacent.get(0);
120	    }
121	
122	    /**
123	     * Returns a random set of patches from getFreePatches() based on a given rate
124	     * getFreePatches() returns a list of size n, only (n*rate) random locations are returned
125	     * @param rateOfGeneration The rate
126	     */
127	    public List<Location> getRandomFreePatches(double rateOfGeneration)
128	    {
129	        List<Location> patches = getFreePatches();
130	        List<Location> randPatches = new ArrayList<>();
131	        for(int i=0; i<rateOfGeneration* patches.size(); i++)
132	        {
133	            Location selectedPatch = patches.get(rand.nextInt(patches.size()));
134	            randPatches.add(selectedPatch);
135	            for(Location loc : adjacentLocations(selectedPatch)){
136	                // avoids duplicates in the patches
137	                patches.remove(loc);
138	            }
139	        }
140	        return randPatches;
141	    }
142	
143	    /**
144	     * Gets the free patches in the field and returns them.
145	     * A 'patch' is a 3x3 square of locations, the locations in the list are the centers of said squares
146	     * Patches do not overlap, so the adjacent locations of one patch don't have common locations with
147	     * the adjacent locations of any other square
148	     *
149	     * @return The list of free patches in the field.
150	     */
151	    public List<Location> getFreePatches()
152	    {
153	        List<Location> res = new ArrayList<>();
154	        for(int i=0; i<field.length; i++){
155	            for(int j=0; j<field[1].length; j++){
156	                if (field[i][j] == null){
157	                    List<Location> nearby = adjacentLocations(new Location(i, j));
158	                    boolean allNulls = true;
159	                    for(Location loc : nearby){
160	                        if(getObjectAt(loc) != null){
161	                            allNulls = false;
162	                        }
163	                    }
164	                    if(allNulls){
165	                        res.add(new Location(i, j));
166	                    }
167	                }
168	            }
169	        }
170	
171	        return res;
172	    }
173	
174	    /**
175	     * Get a shuffled list of the free adjacent locations.
176	     * @param location Get locations adjacent to this.
177	     * @return A list of free adjacent locations.
178	     */
179	    public List<Location> getFreeAdjacentLocations(Location location)
180	    {
181	        List<Location> free = new LinkedList<>();
182	        List<Location> adjacent = adjacentLocations(location);
183	        for(Location next : adjacent) {
184	            Object objectAtNext = getObjectAt(next);
185	            if(objectAtNext == null) {
186	                free.add(next);
187	            }
188	        }
189	        return free;
190	    }
191	
192	    /**
193	     * Try to find a free location that is adjacent to the
194	     * given location. If there is none, return null.
195	     * The returned location will be within the valid bounds
196	     * of the field.
197	     * @param location The location from which to generate an adjacency.
198	     * @return A valid location within the grid area.
199	     */
200	    public Location freeAdjacentLocation(Location location)
201	    {
202	        // The available free ones.
203	        List<Location> free = getFreeAdjacentLocations(location);
204	        if(free.size() > 0) {
205	            return free.get(0);
206	        }
207	        else {
208	            return null;
209	        }
210	    }
211	
212	    /**
213	     * Returns adjacent locations in the field containing a certain class
214	     * For example, adjacentSpecies(location, Grass.class) returns the adjacent locations with Grass
215	     * @param location The location of an organism.
216	     * @param speciesClass The type of species.
217	     * @return adjacentSpecies A list of adjacent locations with the specified species 
218	     */
219	    public List<Location> adjacentLocationsWithSpecies(Location location, Class<?> speciesClass) {
220	        List<Location> free = adjacentLocations(location);
221	        List<Location> res = new ArrayList<>();
222	        for (Location loc : free) {
223	            if (getObjectAt(loc) != null && getObjectAt(loc).getClass()==speciesClass) {
224	                res.add(loc);
225	            }
226	        }
227	        return res;
228	    }
229	
230	    /**
231	     * Return a shuffled list of locations adjacent to the given one.
232	     * The list will not include the location itself.
233	     * All locations will lie within the grid.
234	     * @param location The location from which to generate adjacencies.
235	     * @return A list of locations adjacent to that given.
236	     */
237	    public List<Location> adjacentLocations(Location location)
238	    {
239	        assert location != null : "Null location passed to adjacentLocations";
240	        // The list of locations to be returned.
241	        List<Location> locations = new LinkedList<>();
242	        if(location != null) {
243	            int row = location.getRow();
244	            int col = location.getCol();
245	            for(int roffset = -1; roffset <= 1; roffset++) {
246	                int nextRow = row + roffset;
247	                if(nextRow >= 0 && nextRow < depth) {
248	                    for(int coffset = -1; coffset <= 1; coffset++) {
249	                        int nextCol = col + coffset;
250	                        // Exclude invalid locations and the original location.
251	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
252	                            locations.add(new Location(nextRow, nextCol));
253	                        }
254	                    }
255	                }
256	            }
257	            
258	            // Shuffle the list. Several other methods rely on the list
259	            // being in a random order.
260	            Collections.shuffle(locations, rand);
261	        }
262	        return locations;
263	    }
264	
265	    /**
266	     * Return the depth of the field.
267	     * @return The depth of the field.
268	     */
269	    public int getDepth()
270	    {
271	        return depth;
272	    }
273	    
274	    /**
275	     * Return the width of the field.
276	     * @return The width of the field.
277	     */
278	    public int getWidth()
279	    {
280	        return width;
281	    }
282	}
