3	/**
4	 * This class models grass.
5	 * Grass can germinate,grow and get eaten by animals.
6	 * @version 2022.03.02
7	 */
8	public class Grass extends Plant
9	{
10	    private static int FOOD_VALUE;
11	    private static double GERMINATION_RATE = 0.1;
12	
13	    /**
14	     * Returns the food value of the grass.
15	     * @return int The food value of the grass.
16	     */
17	    protected int FOOD_VALUE()
18	    {
19	        return FOOD_VALUE;
20	    }
21	
22	    /**
23	     * Creates grass with a random stage of growth.
24	     * However, the maximum number of stages is fixed at 3,
25	     * and the growth rate is fixed at 2 steps per stage.
26	     *
27	     * @param field The field currently occupied.
28	     * @param location The location within the field.
29	     */
30	    public Grass(Field field, Location location)
31	    {
32	        super(field, location);
33	
34	        NUMBER_OF_STAGES = 3;
35	        STEPS_PER_STAGE = 2;
36	        STAGE_OF_GROWTH = rand.nextInt(NUMBER_OF_STAGES);
37	        FOOD_VALUE = STAGE_OF_GROWTH;
38	
39	    }
40	
41	
42	    /**
43	     * Make the grass act.
44	     * The germination rate of grass is affected by weather.
45	     * @param newGrass To store the newly germinated grass.
46	     * @param environment The environment that the grass resides in.
47	     */
48	    public void act(List<Actor> newGrass, Environment environment)
49	    {
50	        if (environment.getWeather().getCurrentWeather() == WeatherType.SUNNY){
51	            changeGerminationRate(0.15);
52	        }
53	
54	        else if (environment.getWeather().getCurrentWeather() != WeatherType.SUNNY){
55	            changeGerminationRate(0.1);
56	        }
57	
58	        if(isAlive() && environment.getTime().isDay() && rand.nextDouble() <= GERMINATION_RATE && (environment.getWeather().getCurrentWeather() != (WeatherType.CLOUDY))) {
59	            germinate(newGrass);
60	        }
61	    }
62	
63	    /**
64	     * Check whether this grass is to germinate at this step.
65	     * New grass will be made into free adjacent locations.
66	     * @param newGrass A list to return newly made grass.
67	     */
68	    protected void germinate(List<Actor> newGrass)
69	    {
70	        // New grass are made into adjacent locations.
71	        // Get a list of adjacent free locations.
72	        Field field = getField();
73	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
74	        for(int b = 0; b < free.size(); b++) {
75	            Location loc = free.remove(0);
76	            Grass young = new Grass(field, loc);
77	            newGrass.add(young);
78	        }
79	    }
80	
81	    /**
82	     * Change the germination rate of grass.
83	     * @param newRate The new germination rate.
84	     */
85	    public void changeGerminationRate(double newRate)
86	    {
87	        if(isAlive()) {
88	            GERMINATION_RATE = newRate;
89	        }
90	    }
91	
92	    /**
93	     * Increment the stage of growth of grass
94	     * Incrementing the growth also increases the food level by 1
95	     * @return true If the grass grows.
96	     * @return false If the grass doesn't grow.
97	     */
98	    public boolean incrementGrowth()
99	    {
100	        if(super.incrementGrowth()) {
101	            FOOD_VALUE++;
102	            return true;
103	        }
104	        return false;
105	    }
106	
107	
108	
109	}
