91	    }
92	
93	    /**
94	     * Returns the current time as a string.
95	     */
96	    public String getCurrentTimeString()
97	    {
98	        return " (" + getCurrentPeriod().toString() + ")" + " Day #" + dayCount + " " + getHourString();
99	    }
100	
101	    /**
102	     * Returns the day count number. 
103	     */
104	    private int getDayCount()
105	    { 
106	        return dayCount; 
107	    }
108	
109	    /**
110	     * Reset the time object
111	     */
