5	/**
6	 * This class is used to start the simulation in order to test different probabilities in the Simulation
7	 * The contents of this class were largely adapted from GeeksForGeeks:
8	 * https://www.geeksforgeeks.org/print-all-possible-combinations-of-r-elements-in-a-given-array-of-size-n/
9	 *
10	 * NOTE: This class has not been fully optimized and will consume several gigabytes of memory.
11	 * Please make sure to optimize in a way that memory is occasionally cleared before using this class
12	 *
13	 * @version 2022.03.2
14	 */
15	public class TestingMain {
16	    private static List<Double[]> allCombs = new ArrayList<>();
17	
18	    public static void main(String[] args) {
19	
20	        tester();
21	        Integer watch = SimulationInfo.HIGHEST_STEPS;
22	        Simulator tempSim;
23	        for(Double[] probs : allCombs){
24	            tempSim = new Simulator(probs[0], probs[1], probs[2], probs[3], probs[4], probs[5], probs[6]);
25	            tempSim.runLongSimulation();
26	            tempSim.simulateOneStep();
27	            tempSim = null;
28	        }
29	        System.out.println("HIGHEST STEPS: " + SimulationInfo.HIGHEST_STEPS + " FOR " + SimulationInfo.HIGHEST_STEP_PROBS.toString());
30	    }
