33	    public static void tester(){
34	        Double[] dubs = new Double[15];
35	        Double[] combs = new Double[7];
36	
37	        int c = 0;
38	        for(double i=0.05; i <= 0.8; i += 0.05){
39	            dubs[c] = i;
40	            c++;
41	        }
42	        int r = 7;
43	        int n = dubs.length;
44	        printCombination(dubs, n, r);
45	    }
46	    static void combinationUtil(Double arr[], Double data[], int start,
47	                                int end, int index, int r)
48	    {
49	        // Current combination is ready to be printed, print it
50	        if (index == r)
51	        {
52	            Double[] res = new Double[r];
53	//            System.out.print("[");
54	            for (int j=0; j<r; j++){
55	//                System.out.print(data[j]+", ");
56	                res[j] = data[j];
57	            }
58	            if (res != null){
59	                allCombs.add(res);
60	            }
61	//            System.out.print("]");
62	            System.out.println("");
63	            return;
64	        }
65	        for (int i=start; i<=end && end-i+1 >= r-index; i++)
66	        {
67	            data[index] = arr[i];
68	            combinationUtil(arr, data, i+1, end, index+1, r);
69	        }
70	    }
71	
72	    static void printCombination(Double arr[], int n, int r)
73	    {
74	        // A temporary array to store all combination one by one
75	        Double data[]=new Double[r];
76	
77	        // Print all combination using temporary array 'data[]'
78	        combinationUtil(arr, data, 0, n-1, 0, r);
79	    }
80	}
